import numpy as np
from scipy import stats
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Check if we have enough data
    if feats.n < 10:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Identify near-duplicates based on correlation
    corr_matrix = np.corrcoef(feats.x.T)
    near_dup_pairs = set()
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            if abs(corr_matrix[i,j]) >= 0.6:
                fid1, fid2 = feats.ids[i], feats.ids[j]
                # Keep the one with higher mean absolute effect size
                if abs(np.mean(feats.x[:,i][feats.y==1]) - np.mean(feats.x[:,i][feats.y==0])) > \
                   abs(np.mean(feats.x[:,j][feats.y==1]) - np.mean(feats.x[:,j][feats.y==0])):
                    near_dup_pairs.add((fid2, fid1))
                else:
                    near_dup_pairs.add((fid1, fid2))

    # Remove near-duplicates
    unique_ids = [fid for fid in feats.ids if not any(fid == dup[0] for dup in near_dup_pairs)]

    # Calculate effect sizes and p-values for all features
    effects = []
    for i, fid in enumerate(feats.ids):
        if fid in unique_ids:
            y0_mean = np.mean(feats.x[:,i][feats.y==0])
            y1_mean = np.mean(feats.x[:,i][feats.y==1])
            effect_size = y1_mean - y0_mean
            t_stat, p_val = stats.ttest_ind(feats.x[:,i][feats.y==1], feats.x[:,i][feats.y==0], equal_var=False)
            effects.append((fid, effect_size, p_val, t_stat))

    # Sort by effect size (absolute value)
    effects.sort(key=lambda x: abs(x[1]), reverse=True)

    # Try to find a driver variable using correlation with outcome
    drivers = []
    if len(effects) > 0:
        # Look for variables with strong effect and low p-value
        for fid, effect_size, p_val, t_stat in effects[:5]:  # Top 5 candidates
            if abs(effect_size) > 0.1 and p_val < 0.05:
                drivers.append(fid)
                break

    # If no driver found, return empty design
    if not drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select features for regression (avoiding near-duplicates)
    selected_features = []
    for fid, effect_size, p_val, t_stat in effects:
        if fid in unique_ids and fid not in drivers:
            selected_features.append(fid)

    # Use top 5 features for regression to keep it small
    selected_features = selected_features[:5]

    # Create products (simple pairwise products of selected features)
    products = []
    for i in range(min(2, len(selected_features))):
        for j in range(i+1, min(3, len(selected_features))):
            products.append((selected_features[i], selected_features[j]))

    # Weighted score: use effect sizes as weights
    loadings = {}
    for fid, effect_size, p_val, t_stat in effects:
        if fid in selected_features:
            loadings[fid] = effect_size

    # Return design with selected features
    return Design(
        drivers=tuple(drivers),
        columns=tuple(selected_features),
        products=tuple(products),
        loadings=loadings
    )

